function genNationalInvites(){ // 根据声望，从弱到强的国家队主动邀请玩家执教
  initNationalManager();
  if(WORLD.userNation) return; // 已在执教国家队，不再邀请
  if(WORLD.nationInvites===undefined) WORLD.nationInvites=[];
  const myRep = coachRep();
  // 声望太低（<15）时基本没有国家队青睐
  if(myRep < 15 && Math.random() < 0.7) return;
  // 按实力排序国家队，找"合适档次"的国家队（实力略高于声望对应档）
  const nations = WC_NATIONS.filter(n=>n!==WORLD.userNation).map(n=>({n, str:natSquadStrength(n)}));
  nations.sort((a,b)=>a.str-b.str); // 从弱到强
  // 玩家声望对应的"可执教实力上限"：声望越高，能执教越强的国家队（实力约 105~175）
  const maxStr = clamp(112 + myRep * 0.6, 115, 175);
  // 从弱到强找 1~2 支实力在合理范围的国家队
  const candidates = nations.filter(x=>x.str >= 105 && x.str <= maxStr);
  if(!candidates.length) return;
  // 只邀请实力接近上限的（从弱到强逐步提升）
  const target = candidates.filter(x=>x.str >= maxStr - 12);
  const pool = target.length ? target : candidates.slice(-3);
  const invite = pool[Math.floor(Math.random()*pool.length)];
  if(!invite) return;
  // 避免重复邀请同一国家
  if(WORLD.nationInvites.some(i=>i.nat===invite.n)) return;
  WORLD.nationInvites.push({nat:invite.n, str:Math.round(invite.str), season:WORLD.season});
  news("📨 国家队执教邀请", `${invite.n} 足协向你发出执教邀请！球队实力 ${Math.round(invite.str)}。请到「国际足坛」页查看并决定是否接受。`, "good");
}

prospectFate:
function prospectFate(p){
  const pr=profOf(p),d=developmentUse(p);
  const own = ownerOf(p)>=0 && ownerOf(p)===WORLD.userClub;
  const sl = (WORLD.shortlist||[]).find(x=>x.id===p.id);
  const showNum = own || (sl && sl.know>=95);
  // 30 岁才逐步收窄未兑现空间；不再让 24~27 岁球员一边解锁、一边被削潜。
  if(p.age>=30){
    const gap=p.pa-p.ca;
    if(gap>4){const k=Math.min(0.45,0.12+(p.age-30)*0.06)*(1.25-pr*0.025);
      p.pa=Math.max(p.ca,Math.round(p.pa-gap*k));}
    p.value=calcValue(p);return;
  }
  // 新入队的半季苗子不做全年负面评估；旧档信息不足时先记录至少半年的培养。
  const partial=p.createdAbs!=null&&p.createdAbs>WORLD.season*400;
  if(p.age>28||partial||d.weeks<26||d.games<12){p.value=calcValue(p);return;}
  const sh=clamp(d.apps/d.games,0,1),progress=p.ca-d.startCA;
  const struggling=progress<2&&(sh<0.3||pr<8);
  const stallP=struggling?0.04*(1.6-pr*0.06)*(sh<0.3?1.5:1):0;
  const bloomP=progress>=4?0.03*(0.4+pr*0.06)*(sh>0.6?1.4:sh<0.3?0.5:1):0;
  const r=rnd(),a=p.pa;
  if(r<stallP&&p.pa-p.ca>=6){
    p.pa=Math.max(p.ca+2,p.pa-ri(4,10));
    const why=sh<0.3?"这一年上场太少，":"训练里不太上心，";
    if(own) news(`${p.cn} 发展停滞`,`助教的年度报告：${p.cn}${why}进步比预想的慢。教练组把对他的预期从 ${Math.round(a/2)} 下调到 ${Math.round(p.pa/2)}。`,"bad");
    else if(sl) news(`球探简报：${p.cn} 不如预期`,`球探跟了 ${p.cn} 一年，觉得他${why}没长成当初看好的样子，评估已经下调。`,"warn");
  }else if(r<stallP+bloomP){
    p.pa=Math.min(200,p.pa+ri(6,14));
    if(own) news(`${p.cn} 进步神速`,`助教的年度报告：${p.cn} 这一年的进步超出了所有人预料。教练组把对他的预期从 ${Math.round(a/2)} 上调到 ${Math.round(p.pa/2)}。`,"good");
    else if(sl) news(`球探简报：${p.cn} 比预想的好`,`球探说 ${p.cn} 这一年长得很快，${showNum?`潜力评估上调到 ${Math.round(p.pa/2)}`:"评估已经上调"}。`,"good");
  }
  p.value=calcValue(p);
}
